  1	#include <M5Unified.h>
  2	#include <esp_heap_caps.h>
  3	
  4	extern "C" {
  5	#include "core/canvas.h"
  6	#include "core/push_plan.h"
  7	#include "hacks/registry.h"
  8	#include "runner/button_latch.h"
  9	#include "runner/hack_runner.h"
 10	#include "runner/overlay.h"
 11	#include "runner/rotation.h"
 12	#include "runner/start_pick.h"
 13	}
 14	
 15	/* Hacks run on loopTask, whose 8 KB default stack is too small: Rorschach
 16	 * keeps a 9.6 KB array of rectangles on the stack. */
 17	SET_LOOP_TASK_STACK_SIZE(16 * 1024);
 18	
 19	static const int kSize = 466;
 20	static const uint32_t kSliceUs = 10000;
 21	/* Build with -DSTART_HACK=\"galaxy\" (see AGENTS.md) to always start on one
 22	 * hack; otherwise boot picks one at random. */
 23	#ifdef START_HACK
 24	static const char *const kForcedStart = START_HACK;
 25	#else
 26	static const char *const kForcedStart = nullptr;
 27	#endif
 28	
 29	static const uint32_t kStatsEveryMs = 5000;
 30	static const uint32_t kNameShownMs = 5000;
 31	
 32	/* Seconds before moving on to the next hack; build with -DROTATE_SECONDS=5 to
 33	 * shorten it for leak testing, or 0 to stay put. */
 34	#ifndef ROTATE_SECONDS
 35	#define ROTATE_SECONDS 90
 36	#endif
 37	static const uint32_t kRotateMs = ROTATE_SECONDS * 1000u;
 38	static const int kNameY = kSize / 2;
 39	static const int kFpsY = kSize - 40;
 40	
 41	/* M5Unified reads the buttons as active-low GPIOs, and only inside
 42	 * M5.update(), so a press during a long hack step would go unseen. A small
 43	 * task on the otherwise idle core 0 samples both pins every few milliseconds
 44	 * (it preempts nothing the hacks run on) and a latch keeps the presses. The
 45	 * pin must hold its new level for the settle time, which rejects bounce. */
 46	static const gpio_num_t kPinButtonA = GPIO_NUM_2;
 47	static const gpio_num_t kPinButtonB = GPIO_NUM_1;
 48	static const uint32_t kButtonPollMs = 5;
 49	static const uint32_t kButtonSettleMs = 30;
 50	
 51	static ButtonLatch latchA, latchB;
 52	
 53	static void buttonTask(void *) {
 54	  for (;;) {
 55	    uint32_t now = millis();
 56	    button_latch_sample(&latchA, gpio_get_level(kPinButtonA) == 0, now);
 57	    button_latch_sample(&latchB, gpio_get_level(kPinButtonB) == 0, now);
 58	    vTaskDelay(pdMS_TO_TICKS(kButtonPollMs));
 59	  }
 60	}
 61	
 62	static Canvas canvas;
 63	static HackRunner *runner;
 64	static Overlay overlay;
 65	static Rotation rotation;
 66	static uint32_t frames;
 67	static uint32_t statsAt;
 68	static uint32_t stepUs, pushUs, waitUs, rowsPushed;
 69	static PushRow pushRows[kSize];
 70	
 71	static void halt(const char *msg) {
 72	  Serial.println(msg);
 73	  M5.Display.fillScreen(0x000000);
 74	  M5.Display.setTextColor(0xFFFFFF);
 75	  M5.Display.setTextDatum(middle_center);
 76	  M5.Display.drawString(msg, M5.Display.width() / 2, M5.Display.height() / 2);
 77	  for (;;) delay(1000);
 78	}
 79	
 80	static void resetStats() {
 81	  frames = stepUs = pushUs = waitUs = rowsPushed = 0;
 82	  statsAt = millis();
 83	}
 84	
 85	/* step/push/wait are mean milliseconds per frame spent in the hack, in
 86	 * pushImage, and waiting out what is left of the hack's requested delay after
 87	 * the push (including button polling). rows is the mean number of canvas rows
 88	 * sent to the display per frame (466 is a full push), counting overlay redraws
 89	 * made while waiting. */
 90	static void printStats(const char *tag) {
 91	  float n = frames ? (float)frames : 1.0f;
 92	  Serial.printf(
 93	      "%s %s fps=%.1f step=%.1fms push=%.1fms wait=%.1fms rows=%.0f heap=%u "
 94	      "psram=%u\n",
 95	      tag, g_hacks[runner_index(runner)]->name,
 96	      frames * 1000.0f / kStatsEveryMs, stepUs / n / 1000.0f,
 97	      pushUs / n / 1000.0f, waitUs / n / 1000.0f, rowsPushed / n,
 98	      (unsigned)ESP.getFreeHeap(),
 99	      (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
100	}
101	
102	/* Overlay text is stamped into the canvas just for the push, then the pixels
103	 * under it are put back. Drawing on the display after the push flickered,
104	 * because the next push wiped the text for a moment. The canvas must end up
105	 * as the hack left it, since hacks draw incrementally. M5Canvas wraps the
106	 * canvas buffer so M5GFX's fonts can draw into it; the DejaVu fonts are 1-bit,
107	 * so only pure black and white are written (the same in either byte order). */
108	static const int kPatchMaxH = 48;
109	static const int kPatchMargin = 2;
110	
111	struct Patch {
112	  int x, y, w, h;
113	  uint16_t *saved;
114	};
115	
116	static M5Canvas stamp;
117	static Patch namePatch, fpsPatch;
118	
119	static void stampText(Patch *p, const char *text, int cx, int cy,
120	                      const lgfx::IFont *font) {
121	  stamp.setFont(font);
122	  stamp.setTextDatum(middle_center);
123	  int w = stamp.textWidth(text) + 2 * kPatchMargin;
124	  int h = stamp.fontHeight() + 2 * kPatchMargin;
125	  p->w = w < kSize ? w : kSize;
126	  p->h = h < kPatchMaxH ? h : kPatchMaxH;
127	  p->x = cx - p->w / 2;
128	  p->y = cy - p->h / 2;
129	  canvas_copy_rect(&canvas, p->x, p->y, p->w, p->h, p->saved);
130	  stamp.setTextColor(0x000000);
131	  for (int dy = -1; dy <= 1; dy++)
132	    for (int dx = -1; dx <= 1; dx++)
133	      if (dx || dy) stamp.drawString(text, cx + dx, cy + dy);
134	  stamp.setTextColor(0xFFFFFF);
135	  stamp.drawString(text, cx, cy);
136	  canvas_mark_dirty(&canvas, p->x, p->y, p->w, p->h);
137	}
138	
139	static void unstamp(Patch *p) {
140	  if (p->w) canvas_paste_rect(&canvas, p->x, p->y, p->w, p->h, p->saved);
141	  p->w = 0;
142	}
143	
144	/* Whole rows are sent inside one startWrite: each call then costs about 5 us
145	 * instead of 16. */
146	static void sinkBegin(void *) { M5.Display.startWrite(); }
147	static void sinkEnd(void *) { M5.Display.endWrite(); }
148	static void sinkRow(void *, int y, int x0, int x1) {
149	  M5.Display.pushImage(x0, y, x1 - x0 + 1, 1, canvas.px + y * kSize + x0);
150	}
151	static void sinkAll(void *) {
152	  M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
153	}
154	static const PushSink pushSink = {nullptr, sinkBegin, sinkRow, sinkAll, sinkEnd};
155	
156	static void present() {
157	  uint32_t now = millis();
158	  if (overlay_name_visible(&overlay, now))
159	    stampText(&namePatch, g_hacks[runner_index(runner)]->name, kSize / 2,
160	              kNameY, &fonts::DejaVu24);
161	  if (overlay_fps_visible(&overlay)) {
162	    char text[16];
163	    overlay_fps_text(&overlay, text, sizeof text);
164	    stampText(&fpsPatch, text, kSize / 2, kFpsY, &fonts::DejaVu18);
165	  }
166	  overlay_drawn(&overlay, now);
167	  rowsPushed += push_present(&canvas, pushRows, &pushSink);
168	  unstamp(&fpsPatch);
169	  unstamp(&namePatch);
170	}
171	
172	/* Whatever started the hack, the name shows again, the rotation countdown
173	 * restarts and the stats begin afresh. */
174	static void hackStarted() {
175	  uint32_t now = millis();
176	  overlay_hack_started(&overlay, now);
177	  rotation_reset(&rotation, now);
178	  resetStats();
179	}
180	
181	/* Returns true if a button switched hacks. */
182	static bool pollButtons() {
183	  bool switched = false;
184	  uint32_t pressedAt = 0;
185	  if (button_latch_take(&latchA, &pressedAt)) {
186	    runner_next(runner);
187	    switched = true;
188	  }
189	  if (button_latch_take(&latchB, &pressedAt)) {
190	    runner_prev(runner);
191	    switched = true;
192	  }
193	  if (switched) {
194	    Serial.printf("switch -> %s press_waited=%ums heap=%u psram=%u\n",
195	                  g_hacks[runner_index(runner)]->name,
196	                  (unsigned)(millis() - pressedAt),
197	                  (unsigned)ESP.getFreeHeap(),
198	                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
199	    hackStarted();
200	  }
201	  return switched;
202	}
203	
204	/* Returns true if the timer moved on to the next hack. */
205	static bool pollRotation() {
206	  if (!rotation_due(&rotation, millis())) return false;
207	  runner_next(runner);
208	  Serial.printf("rotate -> %s heap=%u psram=%u\n",
209	                g_hacks[runner_index(runner)]->name, (unsigned)ESP.getFreeHeap(),
210	                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
211	  hackStarted();
212	  return true;
213	}
214	
215	/* A tap anywhere toggles the fps readout. Call right after M5.update(), which
216	 * is the only place the touch edge is recorded. */
217	static void pollTouch() {
218	  if (M5.Touch.getDetail().wasPressed()) overlay_toggle_fps(&overlay);
219	}
220	
221	void setup() {
222	  auto cfg = M5.config();
223	  M5.begin(cfg);
224	  Serial.begin(115200);
225	  M5.Display.setSwapBytes(false);
226	
227	  button_latch_init(&latchA, kButtonSettleMs);
228	  button_latch_init(&latchB, kButtonSettleMs);
229	  xTaskCreatePinnedToCore(buttonTask, "buttons", 2048, nullptr, 2, nullptr, 0);
230	
231	  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
232	    halt("PSRAM alloc failed");
233	  stamp.setBuffer(canvas.px, kSize, kSize, 16);
234	  namePatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
235	  fpsPatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
236	  if (!namePatch.saved || !fpsPatch.saved) halt("PSRAM alloc failed");
237	  runner = runner_create(&canvas);
238	  if (!runner) halt("hack start failed");
239	  int first = start_pick_index(g_hacks, g_hack_count, kForcedStart, esp_random());
240	  if (kForcedStart && start_find_hack(g_hacks, g_hack_count, kForcedStart) < 0)
241	    Serial.printf("START_HACK \"%s\" not found, starting at random\n",
242	                  kForcedStart);
243	  if (runner_start(runner, first) != 0) halt("hack start failed");
244	  overlay_init(&overlay, kNameShownMs);
245	  rotation_init(&rotation, kRotateMs, millis());
246	  hackStarted();
247	  printStats("boot");
248	  resetStats();
249	}
250	
251	void loop() {
252	  M5.update();
253	  if (!pollButtons()) pollRotation();
254	  pollTouch();
255	
256	  uint32_t t0 = micros();
257	  unsigned long delayUs = runner_step(runner);
258	  uint32_t t1 = micros();
259	  present();
260	  uint32_t t2 = micros();
261	  frames++;
262	  overlay_frame(&overlay, millis());
263	  stepUs += t1 - t0;
264	  pushUs += t2 - t1;
265	
266	  /* Only the push counts against the delay. A hack's delay is the pause after
267	   * it draws, so a hack that asks for a one-second hold must still get it
268	   * however long its own step took. */
269	  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
270	  uint32_t waitedUs = 0;
271	  bool switched = false;
272	  while (!switched && waitedUs < waitUsTarget) {
273	    uint32_t slice =
274	        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
275	    delayMicroseconds(slice);
276	    waitedUs += slice;
277	    M5.update();
278	    switched = pollButtons() || pollRotation();
279	    if (!switched) pollTouch();
280	    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
281	  }
282	  if (!switched) waitUs += micros() - t2;
283	
284	  if (millis() - statsAt >= kStatsEveryMs) {
285	    printStats("run");
286	    resetStats();
287	  }
288	}

