 28	  free(rows);
 29	  free(shadow);
 30	  canvas_free(&cv);
 31	}
 32	
 33	static void on_begin(void *ctx) { (void)ctx; calls++; }
 34	static void on_end(void *ctx) { (void)ctx; calls++; }
 35	static void on_row(void *ctx, int y, int x0, int x1) {
 36	  (void)ctx;
 37	  calls++;
 38	  memcpy(shadow + (size_t)y * W + x0, cv.px + (size_t)y * W + x0,
 39	         (size_t)(x1 - x0 + 1) * sizeof(uint16_t));
 40	}
 41	static void on_all(void *ctx) {
 42	  (void)ctx;
 43	  calls++;
 44	  memcpy(shadow, cv.px, (size_t)W * H * sizeof(uint16_t));
 45	}
 46	static const PushSink sink = {NULL, on_begin, on_row, on_all, on_end};
 47	
 48	static int present(void) { return push_present(&cv, rows, &sink); }
 49	static bool shadow_matches_canvas(void) {
 50	  return memcmp(shadow, cv.px, (size_t)W * H * sizeof(uint16_t)) == 0;
 51	}
 52	
 53	#define OVERLAY_X 133
 54	#define OVERLAY_Y 218
 55	#define OVERLAY_W 200
 56	#define OVERLAY_H 30
 57	static uint16_t saved[OVERLAY_W * OVERLAY_H];
 58	
 59	/* Mirrors present() in main.cpp: text is written straight into the canvas,
 60	 * marked dirty by hand, pushed, then the hack's pixels are pasted back. */
 61	static void stamp(void) {
 62	  canvas_copy_rect(&cv, OVERLAY_X, OVERLAY_Y, OVERLAY_W, OVERLAY_H, saved);
 63	  for (int y = OVERLAY_Y; y < OVERLAY_Y + OVERLAY_H; y++)
 64	    for (int x = OVERLAY_X; x < OVERLAY_X + OVERLAY_W; x++) cv.px[y * W + x] = 0xFFFF;
 65	  canvas_mark_dirty(&cv, OVERLAY_X, OVERLAY_Y, OVERLAY_W, OVERLAY_H);
 66	}
 67	static void unstamp(void) {
 68	  canvas_paste_rect(&cv, OVERLAY_X, OVERLAY_Y, OVERLAY_W, OVERLAY_H, saved);
 69	}
